//! Cache DATA from borrowed recorded ORIGINAL BYTES, never lossy raw-page substitution.
use std::{collections::BTreeMap,sync::Arc,io};
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_allow_annotations::PatternOperation,key_policy_control::{self as kc,Control},lint::{Site,AllowUse}};
/// Unsealed DATA callback. Only the actual private source host can certify EOF.
pub trait OriginalBytesPages{fn for_each(&self,visit:&mut dyn FnMut(&str,&[u8])->Result<bool,Failure>)->Result<bool,Failure>;}
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn checked(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}checked(b,poll)?;pending}
struct Scratch{budget:Arc<Budget>,ok:bool}impl Drop for Scratch{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
fn row<C:Control,T>(c:&mut C,v:&mut Vec<T>)->Result<(),C::Error>{if v.len()<v.capacity(){return Ok(())}let target=v.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let bound=target.checked_mul(4).ok_or_else(||c.overflow())?;kc::reserve(c,||bound.checked_mul(std::mem::size_of::<T>())?.checked_add(128))?;v.try_reserve_exact(target-v.len()).map_err(|_|c.allocation_failed())?;if v.capacity()>bound{return Err(c.allocation_failed())}Ok(())}
pub struct CacheData{sites:Vec<Site>,allow_used:Vec<AllowUse>,allow_digests:BTreeMap<String,[u8;20]>}
impl CacheData{pub fn sites(&self)->&[Site]{&self.sites}pub fn allow_used(&self)->&[AllowUse]{&self.allow_used}pub fn allow_digests(&self)->&BTreeMap<String,[u8;20]>{&self.allow_digests}pub fn metadata(&self)->&'static crate::lint::Meta{&crate::cache_policy::META}}
/// Decode exactly Python utf8 errors=ignore, then the shared universal-newline policy.
/// Kept separate from the old lossy Tree view used for ALLOW whole-file digests.
fn ignoring(bytes:&[u8],c:&mut PatternOperation<'_>)->Result<String,Failure>{kc::reserve(c,||bytes.len().checked_mul(8)?.checked_add(512))?;let mut text=String::new();text.try_reserve_exact(bytes.len()).map_err(|_|c.allocation_failed())?;let bound=bytes.len().checked_mul(4).and_then(|n|n.checked_add(128)).ok_or_else(||c.overflow())?;if text.capacity()>bound{return Err(c.allocation_failed())}for chunk in bytes.utf8_chunks(){c.checkpoint()?;text.push_str(chunk.valid());}let text=crate::util::universal_newlines(text);if text.capacity()>bound{return Err(c.allocation_failed())}c.checkpoint()?;Ok(text)}
fn file(relative:&str,bytes:&[u8],out:&mut CacheData,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<(),Failure>{let mut scratch=Scratch{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let pending=(||{let mut temporary=PatternOperation{patterns,budget:&scratch.budget,poll};let persistent=std::cell::RefCell::new(PatternOperation{patterns,budget:root,poll});let text=ignoring(bytes,&mut temporary)?;let used=std::cell::Cell::new(false);let output=std::cell::RefCell::new(out);
 crate::cache_policy::judge_using(&text,&mut temporary,&mut|number,code,_|{let mut out=output.borrow_mut();let mut persistent=persistent.borrow_mut();let code=code.unwrap_or_default();persistent.reserve(code.capacity())?;let value=AllowUse{rel:kc::own(&mut *persistent,relative)?,line:u32::try_from(number).map_err(|_|persistent.overflow())?,name:kc::own(&mut *persistent,"cache")?,code};if !out.allow_used.contains(&value){row(&mut *persistent,&mut out.allow_used)?;out.allow_used.push(value);}used.set(true);Ok(())},&mut|number,message,_|{let mut out=output.borrow_mut();let mut persistent=persistent.borrow_mut();row(&mut *persistent,&mut out.sites)?;out.sites.push(Site{rule:kc::own(&mut *persistent,"hand_rolled")?,rel:kc::own(&mut *persistent,relative)?,line:u32::try_from(number).map_err(|_|persistent.overflow())?,msg:kc::own(&mut *persistent,message)?,key:String::new(),ident:String::new()});Ok(())})?;
 if used.get(){kc::reserve(&mut temporary,||bytes.len().checked_mul(16)?.checked_add(512))?;let original=crate::util::universal_newlines(String::from_utf8_lossy(bytes).into_owned());let max=bytes.len().checked_mul(8).and_then(|n|n.checked_add(512)).ok_or_else(||temporary.overflow())?;if original.capacity()>max{return Err(temporary.allocation_failed())}let mut out=output.borrow_mut();let mut persistent=persistent.borrow_mut();kc::reserve(&mut *persistent,||Some(2048+std::mem::size_of::<(String,[u8;20])>()))?;out.allow_digests.insert(kc::own(&mut *persistent,relative)?,crate::captured_raw_file::source_allow_digest_text(&original));}
 checked(&scratch.budget,poll)?;Ok(())})();let pending=finish(pending,&scratch.budget,poll);scratch.ok=pending.is_ok();drop(scratch);finish(pending,root,poll)}
pub fn collect(pages:&dyn OriginalBytesPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<CacheData,Failure>{collect_using(pages,root,poll,None)}
pub fn collect_with_patterns(pages:&dyn OriginalBytesPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<CacheData,Failure>{collect_using(pages,root,poll,Some(patterns))}
fn collect_using(pages:&dyn OriginalBytesPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<CacheData,Failure>{checked(root,poll)?;let mut output=CacheData{sites:Vec::new(),allow_used:Vec::new(),allow_digests:BTreeMap::new()};let pending=(||{if !pages.for_each(&mut|relative,bytes|{file(relative,bytes,&mut output,root,poll,patterns)?;Ok(true)})?{return Err("cache original-byte source stopped before actual hidden-inclusive CODE EOF".into())}Ok(output)})();finish(pending,root,poll)}
